# brute-force wythoff verification against DP for all 1..25
def bruteforce_loses(N):
    win=[[False]*(N+1) for _ in range(N+1)]
    loses=set()
    for a in range(N+1):
        for b in range(N+1):
            if a==0 and b==0:
                win[a][b]=False
                continue
            w=False
            for k in range(1,a+1):
